for (const name of ["alice", "bob", "outsider"]) {
    insomnia.environment.set(name + "_id", "insomnia_" + name + "_" + suffix);
    insomnia.environment.set(name + "_token", "");
}
for (const key of ["game_id", "game_id_lower", "current_player_id", "other_player_id", "current_player_token", "other_player_token"]) insomnia.environment.set(key, "");

